  /* ---- board ---- */
  var rowsEl = document.getElementById('rows');
  var countEl = document.getElementById('count');

  function currentFilter() {
    return {
      q: (document.getElementById('q').value || '').trim().toLowerCase(),
      category: document.getElementById('category').value,
      chain: document.getElementById('chain').value,
      verdict: document.getElementById('verdict').value,
      watchlist: document.getElementById('watchlist').checked,
      sort: document.getElementById('sort').value,
    };
  }

  function filteredRows() {
    var f = currentFilter();
    var rows = DATA.rows.filter(function (r) {
      if (f.watchlist && !WATCH[r.slug]) return false;
      if (f.category !== 'all' && r.category !== f.category) return false;
      if (f.chain !== 'all' && r.chains.indexOf(f.chain) === -1) return false;
      if (f.verdict !== 'all' && r.verdict !== f.verdict) return false;
      if (f.q && (r.name + ' ' + r.slug + ' ' + (r.category || '')).toLowerCase().indexOf(f.q) === -1) return false;
      return true;
    });
    var key = f.sort;
    rows = rows.slice();
    if (key === 'tvl') rows.sort(function (a, b) { return b.tvl_usd - a.tvl_usd; });
    else if (key === 'growth') rows.sort(function (a, b) { return (b.change_7d || 0) - (a.change_7d || 0); });
    else if (key === 'age') rows.sort(function (a, b) { return (b.age_days || 0) - (a.age_days || 0); });
    else if (key === 'net') rows.sort(function (a, b) { return whatIfEcon(b).net - whatIfEcon(a).net; });
    else if (key === 'odds') rows.sort(function (a, b) { return b.launch_odds - a.launch_odds; });
    else if (key === 'readiness') rows.sort(function (a, b) { return b.readiness - a.readiness; });
    else rows.sort(function (a, b) { return b.implied_value_usd - a.implied_value_usd; });
    return rows;
  }

  /* ---- what-if: deposit / share / T-bill recompute from the row's own base numbers ---- */
  var WI = { deposit: 0, share: 1, tbill: 4 };
  function whatIfEcon(r) {
    var f = r.farm;
    var cap = WI.deposit > 0 ? WI.deposit : f.capital_usd;
    var weeks = Math.max(1, Math.ceil(f.hold_days / 7));
    var fees = (cap >= 150 ? 8 : 4) + 2 * weeks + 2;
    var tbill = cap * (WI.tbill / 100) * f.hold_days / 365;
    var scale = WI.share * (cap / f.capital_usd);
    var sliceLow = f.slice_low_cond_usd * r.launch_odds * scale;
    var net = sliceLow - fees - tbill;
    var beBase = f.slice_low_cond_usd * scale;
    return {
      net: net,
      perHour: net / f.hours,
      be: beBase > 0 ? (fees + tbill) / beBase : 9999,
      verdict: net >= 60 && net >= 0.04 * cap ? 'FARM' : net > 0 ? 'THIN' : 'SKIP',
    };
  }
  function beText(be) { return be > 1 ? '>100%' : (be * 100).toFixed(1) + '%'; }

  function renderBoard() {
    var rows = filteredRows();
    rowsEl.innerHTML = '';
    var gmin = Math.log10(Math.min.apply(null, DATA.rows.map(function (r) { return r.band_lo_usd; })));
    var gmax = Math.log10(Math.max.apply(null, DATA.rows.map(function (r) { return r.band_hi_usd; })));
    var span = Math.max(gmax - gmin, 0.01);
    rows.forEach(function (r) {
      var w = whatIfEcon(r);
      var tr = el('tr');
      tr.setAttribute('data-slug', r.slug);
      tr.appendChild(el('td', { class: 'num' }, String(r.rank)));
      var nameTd = el('td');
      nameTd.appendChild(el('span', null, esc(r.name)));
      if (WATCH[r.slug]) nameTd.appendChild(el('span', { class: 'watch' }, ' ● watchlist'));
      tr.appendChild(nameTd);
      tr.appendChild(el('td', null, esc(r.category || '—')));
      tr.appendChild(el('td', { class: 'num' }, compact(r.tvl_usd)));
      var g = el('td', { class: 'num ' + ((r.change_7d || 0) >= 0 ? 'pos' : 'neg') }, pct(r.change_7d));
      tr.appendChild(g);
      tr.appendChild(el('td', { class: 'num' }, ageText(r.age_days)));
      tr.appendChild(el('td', { class: 'num' }, money(r.implied_value_usd)));
      tr.appendChild(el('td', { class: 'num' }, (r.launch_odds * 100).toFixed(0) + '%'));
      var rangeTd = el('td');
      var bar = el('div', { class: 'rangebar', title: money(r.band_lo_usd) + ' – ' + money(r.band_hi_usd) });
      var lo = (Math.log10(r.band_lo_usd) - gmin) / span * 100;
      var hi = (Math.log10(r.band_hi_usd) - gmin) / span * 100;
      var mid = (Math.log10(r.implied_value_usd) - gmin) / span * 100;
      var seg = el('div', { class: 'range-seg', style: 'left:' + lo.toFixed(1) + '%;width:' + Math.max(hi - lo, 1).toFixed(1) + '%;' });
      var mark = el('div', { class: 'range-mark', style: 'left:' + mid.toFixed(1) + '%;' });
      bar.appendChild(seg);
      bar.appendChild(mark);
      rangeTd.appendChild(bar);
      tr.appendChild(rangeTd);
      var vTd = el('td');
      vTd.appendChild(el('span', { class: 'badge ' + w.verdict }, w.verdict));
      tr.appendChild(vTd);
      tr.appendChild(el('td', { class: 'num ' + (w.net >= 0 ? 'pos' : 'neg') }, money2(w.net)));
      tr.appendChild(el('td', { class: 'num ' + (w.perHour >= 0 ? 'pos' : 'neg') }, money2(w.perHour)));
      tr.appendChild(el('td', { class: 'num' }, beText(w.be)));
      tr.addEventListener('click', function () { openDetail(r.slug); });
      rowsEl.appendChild(tr);
    });
    countEl.textContent = rows.length + ' of ' + DATA.rows.length + ' protocols shown — ranks by implied value; the verdict column is the netted farm call.';
    var counts = { FARM: 0, THIN: 0, SKIP: 0 };
    DATA.rows.forEach(function (r) { counts[whatIfEcon(r).verdict]++; });
    var dep = WI.deposit > 0 ? '$' + WI.deposit.toLocaleString('en-US') : 'plan capital';
    var sum = document.getElementById('wi-summary');
    if (sum) sum.textContent = 'At ' + dep + ' · ' + (0.0025 * WI.share).toFixed(4) + '% · ' + WI.tbill + '% T-bill: ' + counts.FARM + ' FARM / ' + counts.THIN + ' THIN / ' + counts.SKIP + ' SKIP (base ' + DATA.verdict_counts.FARM + '/' + DATA.verdict_counts.THIN + '/' + DATA.verdict_counts.SKIP + ').';
  }

